            <div class="form-field"><label for="customer_id">Customer <span class="optional-label">optional</span></label><select id="customer_id" name="customer_id"><option value="">Walk-in customer</option><?php foreach ($customers as $customer): ?><option value="<?= (int) $customer['id'] ?>" <?= (string) old('customer_id', '', false) === (string) $customer['id'] ? 'selected' : '' ?>><?= esc($customer['full_name']) ?></option><?php endforeach; ?></select><?php if (isset($errors['customer_id'])): ?><p class="field-error"><?= esc($errors['customer_id']) ?></p><?php endif; ?></div>
            <div class="form-field"><label for="quantity">Quantity <span class="required-mark">*</span></label><input id="quantity" name="quantity" type="number" min="1" max="100000" step="1" required value="<?= esc(old('quantity', '1', false), 'attr') ?>" data-sale-quantity><?php if (isset($errors['quantity'])): ?><p class="field-error"><?= esc($errors['quantity']) ?></p><?php endif; ?></div>
            <p class="field-help">Stock and price are checked again when you submit. The total is calculated on the server.</p>
            <div class="form-actions"><button class="button primary" type="submit">Complete sale <span aria-hidden="true">↗</span></button><a class="button secondary" href="<?= site_url('sales') ?>">Cancel</a></div>
